/* ── 제품 옵션(사이즈·관리유형·약정기간) 선택 도우미 ── */
(function(){
  var DIM_ORDER = ['sz','cr','tm'];
  var DIM_LAB = { sz:'사이즈', cr:'관리', tm:'기간' };
  function entry(id){ return window.POPT[id]; }
  function key(s){ return s.sz + '|' + s.cr + '|' + s.tm; }
  function has(o, s){ return !!o.p[key(s)]; }
  function tmLab(t){ return (parseInt(t,10)/12) + '년'; }
  function labOf(o, dim, v){ return (o.lab[dim] && o.lab[dim][v]) || v; }
  function opts(id, dim, st){
    var o = entry(id); if(!o) return [];
    st = st || {};
    var vals = [];
    for(var k in o.p){
      if(!o.p.hasOwnProperty(k)) continue;
      var p = k.split('|'), s = { sz:p[0], cr:p[1], tm:p[2] }, ok = true;
      for(var i=0;i<DIM_ORDER.length;i++){
        var d = DIM_ORDER[i];
        if(d === dim) continue;
        if(st[d] && s[d] !== st[d]) { ok = false; break; }
      }
      if(ok && vals.indexOf(s[dim]) < 0) vals.push(s[dim]);
    }
    if(dim === 'tm') vals.sort(function(a,b){ return Number(a)-Number(b); });
    else vals.sort();
    return vals;
  }
  function norm(id, st){
    var o = entry(id); if(!o) return null;
    st = st || {};
    var want = { sz: st.sz || o.d.sz, cr: st.cr || o.d.cr, tm: String(st.tm || o.d.tm) };
    if(has(o, want)) return want;
    var best = null, bs = -1;
    for(var k in o.p){
      if(!o.p.hasOwnProperty(k)) continue;
      var p = k.split('|'), s = { sz:p[0], cr:p[1], tm:p[2] }, sc = 0;
      if(s.sz === want.sz) sc += 4;
      if(s.cr === want.cr) sc += 2;
      if(s.tm === want.tm) sc += 1;
      if(sc > bs){ bs = sc; best = s; }
    }
    return best;
  }
  function price(id, st){
    var o = entry(id); if(!o) return null;
    return o.p[key(st)] || null;
  }
  function basis(id, st){
    var o = entry(id); if(!o) return '';
    var parts = [];
    for(var i=0;i<o.dims.length;i++){
      var d = o.dims[i];
      parts.push(d === 'tm' ? tmLab(st.tm) : labOf(o, d, st[d]));
    }
    return parts.join(' · ');
  }
  function priceHTML(pr){
    if(!pr) return '';
    var s = (pr[1] && pr[1] > pr[0]) ? '<s>월 ' + Number(pr[1]).toLocaleString('ko-KR') + '원</s> ' : '';
    return s + '<b>월 ' + Number(pr[0]).toLocaleString('ko-KR') + '원</b>';
  }
  function rows(id, st){
    var o = entry(id); if(!o) return [];
    return o.dims.map(function(d){
      return {
        dim: d, label: d === 'cr' ? (o.clab || DIM_LAB[d]) : DIM_LAB[d],
        items: opts(id, d, st).map(function(v){
          return { v: v, l: d === 'tm' ? tmLab(v) : labOf(o, d, v) };
        })
      };
    });
  }
  window.POPT_FN = {
    norm: norm, price: price, opts: opts, basis: basis,
    priceHTML: priceHTML, rows: rows, entry: entry, tmLab: tmLab, labOf: labOf
  };
})();
